import numpy as np,json
from scipy.spatial.transform import Rotation
from scipy.optimize import least_squares
from rcb_client import Robot
from PIL import Image
S=json.load(open('/app/output/spec.json')); P=np.array(S['arm']['position_m']); A=np.array(S['arm']['axis']); EE=np.array(S['arm']['end_effector']['position_m'])
def fk(q,pt=EE):
 R=np.eye(3); t=np.zeros(3)
 for p,a,ang in zip(P,A,q):
  ri=Rotation.from_rotvec(a*ang).as_matrix(); t=t+R@(p-ri@p); R=R@ri
 return R@pt+t,R

def ik(pos,Rdes,q):
 def err(x):
  p,R=fk(x); return np.r_[ (p-pos)*4,Rotation.from_matrix(Rdes@R.T).as_rotvec() ]
 lo=np.array([-np.inf,-2.24,-np.inf,-2.57,-np.inf,-2.09,-np.inf]); hi=-lo
 sol=least_squares(err,q,bounds=(lo,hi),max_nfev=200)
 if np.linalg.norm(err(sol.x))>.03: print('IK error',err(sol.x))
 return sol.x
class C:
 def __init__(self): self.r=Robot();self.o=self.r.observe(False);self.grip=0
 def snap(self,name='view'):
  self.o=self.r.observe();
  for k,v in self.o['images'].items(): Image.fromarray(v).save('/app/output/'+name+'_'+k+'.png')
  np.savez('/app/output/'+name+'_depth.npz',**self.o.get('depth',{}));json.dump(self.o['proprio'],open('/app/output/'+name+'_prop.json','w'));print('obs',self.o['step'],self.o['done'],self.o['reason'],self.o['proprio'])
 def step(self,a,images=False):
  self.o=self.r.step('delta',a,images=images)
  if self.o['done']: print('DONE',self.o['reason']);raise RuntimeError(self.o['reason'])
 def joints(self,q,n=80):
  for _ in range(n):
   diff=np.array(q)-self.o['proprio']['arm_pos']
   if np.max(abs(diff))<.007: break
   self.step(np.r_[np.zeros(3),np.clip(diff,-.1,.1),self.grip])
 def move(self,pos,R=None,n=80):
  q=np.array(self.o['proprio']['arm_pos']);R= fk(q)[1] if R is None else R; self.joints(ik(np.array(pos),R,q),n)
 def base(self,x,y,yaw=None,n=100):
  for _ in range(n):
   b=np.array(self.o['proprio']['base_pose']);d=np.array([x,y,b[2] if yaw is None else yaw])-b
   if np.max(abs(d))<.003:break
   d[:2]*=min(1,.08/(np.linalg.norm(d[:2])+1e-10));d[2]=np.clip(d[2],-.1,.1)
   self.step(np.r_[d,np.zeros(7),self.grip])
 def hold(self,n=5): self.step([np.r_[np.zeros(10),self.grip].tolist() for _ in range(n)])
if __name__=='__main__':
 c=C();q=c.o['proprio']['arm_pos'];print('fk',fk(q));cam=S['cameras']['robot_wrist']['pose'];print('cam',fk(q,np.array(cam['position_m'])),fk(q)[1]@cam['forward'])
 c.move([.55,0,1.25],Rotation.from_euler('y',180,degrees=True).as_matrix());c.snap('high')
PY
